	return math.sqrt(self:LengthSq())
end

function Lub_Quat:Normalize()
	local len = self:Length()
	if len > 0.0 then
		return Lub_Quat.new(self.X / len, self.Y / len, self.Z / len, self.W / len)
	else
		return Lub_Quat.Identity()
	end
end

function Lub_Quat:Conjugate()
	return Lub_Quat.new(-self.X, -self.Y, -self.Z, self.W)
end

function Lub_Quat:Inverse()
	local lsq = self:LengthSq()
	if lsq > 0.0 then
		local inv = 1.0 / lsq
		return Lub_Quat.new(-self.X * inv, -self.Y * inv, -self.Z * inv, self.W * inv)
	end
	return Lub_Quat.Identity()
end

function Lub_Quat:Lerp(b, t)
	return Lub_Quat.new(
		self.X + (b.X - self.X) * t,
		self.Y + (b.Y - self.Y) * t,
		self.Z + (b.Z - self.Z) * t,
		self.W + (b.W - self.W) * t
	)
end

function Lub_Quat:Slerp(b, t)
	local d = self:Dot(b)
	local bx = b.X
	local by = b.Y
	local bz = b.Z
	local bw = b.W
	if d < 0.0 then
		d = -d
		bx = -bx
		by = -by
		bz = -bz
		bw = -bw
	end
	if d > 0.9995 then
		return Lub_Quat.new(
			self.X + (bx - self.X) * t,
			self.Y + (by - self.Y) * t,
			self.Z + (bz - self.Z) * t,
			self.W + (bw - self.W) * t
		):Normalize()
	end
	local theta = math.atan(math.sqrt(1.0 - d * d), d)
	local sinT = math.sin(theta)
	local s0 = math.sin((1.0 - t) * theta) / sinT
	local s1 = math.sin(t * theta) / sinT
	return Lub_Quat.new(self.X * s0 + bx * s1, self.Y * s0 + by * s1, self.Z * s0 + bz * s1, self.W * s0 + bw * s1)
end

function Lub_Quat:RotateVec3(v)
	local qv = Lub_Vec3.new(self.X, self.Y, self.Z)
	local uv = qv:Cross(v)
	local uuv = qv:Cross(uv)
	return v:Add(uv:Scale(2.0 * self.W):Add(uuv:Scale(2.0)))
end

function Lub_Quat:ToMat4()
	local x2 = self.X + self.X
	local y2 = self.Y + self.Y
	local z2 = self.Z + self.Z
	local xx = self.X * x2
	local xy = self.X * y2
	local xz = self.X * z2
	local yy = self.Y * y2
	local yz = self.Y * z2
	local zz = self.Z * z2
	local wx = self.W * x2
	local wy = self.W * y2
	local wz = self.W * z2
	local r = Lub_Mat4.Zero()
	r.M[0 + 1] = 1 - (yy + zz)
	r.M[1 + 1] = xy - wz
	r.M[2 + 1] = xz + wy
	r.M[3 + 1] = 0.0
	r.M[4 + 1] = xy + wz
	r.M[5 + 1] = 1 - (xx + zz)
	r.M[6 + 1] = yz - wx
	r.M[7 + 1] = 0.0
	r.M[8 + 1] = xz - wy
	r.M[9 + 1] = yz + wx
	r.M[10 + 1] = 1 - (xx + yy)
	r.M[11 + 1] = 0.0
	r.M[12 + 1] = 0.0
	r.M[13 + 1] = 0.0
	r.M[14 + 1] = 0.0
	r.M[15 + 1] = 1.0
	return r
end

function Lub_Quat.FromMat4(m)
	local trace = m.M[0 + 1] + m.M[5 + 1] + m.M[10 + 1]
	if trace > 0.0 then
		local s = 0.5 / math.sqrt(trace + 1.0)
		return Lub_Quat.new(
			(m.M[9 + 1] - m.M[6 + 1]) * s,
			(m.M[2 + 1] - m.M[8 + 1]) * s,
			(m.M[4 + 1] - m.M[1 + 1]) * s,
			0.25 / s
		)
	elseif m.M[0 + 1] > m.M[5 + 1] and m.M[0 + 1] > m.M[10 + 1] then
		local s = 2.0 * math.sqrt(1.0 + m.M[0 + 1] - m.M[5 + 1] - m.M[10 + 1])
		return Lub_Quat.new(
			0.25 * s,
			(m.M[1 + 1] + m.M[4 + 1]) / s,
			(m.M[8 + 1] + m.M[2 + 1]) / s,
			(m.M[9 + 1] - m.M[6 + 1]) / s
		)
	elseif m.M[5 + 1] > m.M[10 + 1] then
		local s = 2.0 * math.sqrt(1.0 + m.M[5 + 1] - m.M[0 + 1] - m.M[10 + 1])
		return Lub_Quat.new(
			(m.M[1 + 1] + m.M[4 + 1]) / s,
			0.25 * s,
			(m.M[6 + 1] + m.M[9 + 1]) / s,
			(m.M[2 + 1] - m.M[8 + 1]) / s
		)
	else
		local s = 2.0 * math.sqrt(1.0 + m.M[10 + 1] - m.M[0 + 1] - m.M[5 + 1])
		return Lub_Quat.new(
			(m.M[8 + 1] + m.M[2 + 1]) / s,
			(m.M[6 + 1] + m.M[9 + 1]) / s,
			0.25 * s,
			(m.M[4 + 1] - m.M[1 + 1]) / s
		)
	end
end

