	r.M[9 + 1] = a[8 + 1] * bm[1 + 1] + a[9 + 1] * bm[5 + 1] + a[10 + 1] * bm[9 + 1] + a[11 + 1] * bm[13 + 1]
	r.M[10 + 1] = a[8 + 1] * bm[2 + 1] + a[9 + 1] * bm[6 + 1] + a[10 + 1] * bm[10 + 1] + a[11 + 1] * bm[14 + 1]
	r.M[11 + 1] = a[8 + 1] * bm[3 + 1] + a[9 + 1] * bm[7 + 1] + a[10 + 1] * bm[11 + 1] + a[11 + 1] * bm[15 + 1]
