	local a03 = a[3 + 1]
	local a10 = a[4 + 1]
	local a11 = a[5 + 1]
	local a12 = a[6 + 1]
	local a13 = a[7 + 1]
	local a20 = a[8 + 1]
	local a21 = a[9 + 1]
