	r.M[8 + 1] = -s
	r.M[10 + 1] = c
	return r
end

function Lub_Mat4.RotateZ(angle)
	local c = math.cos(angle)
	local s = math.sin(angle)
	local r = Lub_Mat4.new()
	r.M[0 + 1] = c
	r.M[1 + 1] = -s
	r.M[4 + 1] = s
	r.M[5 + 1] = c
