function Lub_Mat4.LookAtLh(eye, target, up)
	local z = target:Sub(eye):Normalize()
	local x = up:Cross(z):Normalize()
	local y = z:Cross(x)
	local r = Lub_Mat4.Zero()
	r.M[0 + 1] = x.X
	r.M[1 + 1] = x.Y
	r.M[2 + 1] = x.Z
	r.M[3 + 1] = -x:Dot(eye)
	r.M[4 + 1] = y.X
	r.M[5 + 1] = y.Y
	r.M[6 + 1] = y.Z
	r.M[7 + 1] = -y:Dot(eye)
	r.M[8 + 1] = z.X
	r.M[9 + 1] = z.Y
	r.M[10 + 1] = z.Z
	r.M[11 + 1] = -z:Dot(eye)
	r.M[12 + 1] = 0.0
	r.M[13 + 1] = 0.0
	r.M[14 + 1] = 0.0
	r.M[15 + 1] = 1.0
	return r
end

function Lub_Mat4.PerspectiveLh(fovDeg, aspect, nz, fz)
	local f = 1.0 / math.tan(fovDeg * 3.141592653589793 / 360.0)
	local r = Lub_Mat4.Zero()
	r.M[0 + 1] = f / aspect
	r.M[5 + 1] = f
	r.M[10 + 1] = fz / (fz - nz)
	r.M[11 + 1] = -fz * nz / (fz - nz)
	r.M[14 + 1] = 1.0
	return r
end

function Lub_Mat4.OrthoLh(w, h, nz, fz)
	local r = Lub_Mat4.Zero()
	r.M[0 + 1] = 2 / w
	r.M[5 + 1] = 2 / h
	r.M[10 + 1] = 1 / (fz - nz)
	r.M[11 + 1] = -nz / (fz - nz)
	r.M[15 + 1] = 1.0
	return r
end

function Lub_Mat4.__mul_1(a, b)
	return a:Mul(b)
end

function Lub_Mat4.__mul_2(a, v)
	return a:MulVec4(v)
end

