function Lub_MathUtil.Smoothstep(edge0, edge1, x)
	local t = Lub_MathUtil.Clamp((x - edge0) / (edge1 - edge0), 0.0, 1.0)
	return t * t * (3.0 - 2.0 * t)
end

function Lub_MathUtil.Step(edge, x)
	if x < edge then
		return 0.0
	else
		return 1.0
	end
end

