function Lubx_Assets.Shader(key, vsPath, fsPath)
	local vs
	local vsVersion
	local _
	vs, vsVersion, _, _ = lub.io.load_text(vsPath)
	local fs
	local fsVersion
	local _
	fs, fsVersion, _, _ = lub.io.load_text(fsPath)
	if vs == nil or fs == nil then
		return nil
	end
	return lub.gfx.use_shader(key, vs, fs, vsVersion * 31 + fsVersion)
end

function Lubx_Assets.Wav(key, path)
	local bytes
	local version
	local _
	bytes, version, _, _ = lub.io.load_bytes(path)
	if bytes == nil then
		return nil
	end
	local e
	if
		(function()
			local __tcs_found, __tcs_v = Dict.TryGet(Lubx_Assets.wavs, key, nil)
			e = __tcs_v
			return __tcs_found
		end)() and e.Version == version
	then
		return lub.audio.snd(key, Lubx_Assets.noSamples, e.Channels, e.Rate, version)
	end
	local pcm
	local channels
	local rate
	pcm, channels, rate = lub.audio.decode(bytes)
	if pcm == nil then
		return nil
	end
	local entry = Lubx_WavEntry.new()
	entry.Channels = channels
	entry.Rate = rate
	entry.Version = version
	Lubx_Assets.wavs[key] = entry
	return lub.audio.snd_bytes(key, pcm, channels, rate, version)
end

function Lubx_Assets.RenderTarget(key, w, h, fmt, filter, wrap)
	local opts = {}
	opts.target = true
	opts.filter = __tcs_nget(filter, lub.gfx.LINEAR)
	opts.wrap = __tcs_nget(wrap, lub.gfx.CLAMP)
	return lub.gfx.use_texture(key, w, h, fmt, nil, w * 65536 + h, opts)
end

function Lubx_Assets.Floats(key, usage, path)
	local data
	local version
	local _
	data, version, _, _ = lub.io.load_floats(path)
	if data == nil then
		return nil
	end
	return lub.gfx.use_buffer(key, usage, data, version)
end

