		W = 0,
		H = 0,
		Key = key,
		path = nil,
		pixels = nil,
		format = lub.gfx.RGBA8,
		version = nil,
		dirty = true,
		opts = nil,
	}, Lubx_Atlas)
	return self
end

function Lubx_Atlas.FromPng(key, path, opts)
