		while i < gm.vert_count do
			local x = gm.positions[i * 3 + 1]
			local y = gm.positions[i * 3 + 1 + 1]
			verts[#verts + 1] = x
			verts[#verts + 1] = y
			if x < minX then
				minX = x
			end
			if x > maxX then
				maxX = x
			end
			if y < minY then
				minY = y
			end
			if y > maxY then
				maxY = y
