end

function Lubx_MeshText:Width(s, size)
	local sum = 0.0
	for _, r in utf8.codes(s) do
		local e = self:GlyphFor(r)
		if e ~= nil then
			sum = sum + e.Advance
		end
	end
	return sum * size
end

