function Lubx_Sdf.Flatten(node, nodes)
	local d = {}
	d.op = node.Op
	d.params = node.Params
	if node.Name ~= nil then
		d.name = node.Name
	end
	if node.C ~= nil then
		d.a = Lubx_Sdf.Flatten(node.C, nodes)
	end
	if node.A ~= nil then
		d.a = Lubx_Sdf.Flatten(node.A, nodes)
	end
	if node.B ~= nil then
		d.b = Lubx_Sdf.Flatten(node.B, nodes)
	end
	nodes[#nodes + 1] = d
	return #nodes - 1
end

