				__tcs_t30[#__tcs_t30 + 1] = __tcs_v
			end
		end
	end
	Lubx_Sfx.cache[key] = samples
	return lub.audio.snd(key, samples, 1, 44100, 1)
end

function Lubx_Sfx.Noise(dur, vol, seed)
	local s = __tcs_nget(seed, 0x12345678)
