	return lub.audio.snd(key, samples, 1, 44100, 1)
end

function Lubx_Sfx.Synth(key, dur, version, sample)
	local cachedVersion
	local cached
	if
		(function()
			local __tcs_found, __tcs_v = Dict.TryGet(Lubx_Sfx.synthVersions, key, 0)
			cachedVersion = __tcs_v
			return __tcs_found
		end)()
