function Lubx_Shapes3d.Cylinder(sides)
	local pos = {}
	local nrm = {}
	local indices = {}
	for i = 0, sides - 1 do
		local a = (i * 1.0) / sides * 3.141592653589793 * 2.0
		local nx = math.cos(a)
		local nz = math.sin(a)
		pos[#pos + 1] = nx
		pos[#pos + 1] = -0.5
		pos[#pos + 1] = nz
		nrm[#nrm + 1] = nx
		nrm[#nrm + 1] = 0.0
		nrm[#nrm + 1] = nz
		pos[#pos + 1] = nx
		pos[#pos + 1] = 0.5
		pos[#pos + 1] = nz
		nrm[#nrm + 1] = nx
		nrm[#nrm + 1] = 0.0
