		pos[#pos + 1] = y
		pos[#pos + 1] = 0.0
		nrm[#nrm + 1] = 0.0
		nrm[#nrm + 1] = ny
		nrm[#nrm + 1] = 0.0
		for i = 0, sides - 1 do
			local a = (i * 1.0) / sides * 3.141592653589793 * 2.0
			pos[#pos + 1] = math.cos(a)
			pos[#pos + 1] = y
			pos[#pos + 1] = math.sin(a)
			nrm[#nrm + 1] = 0.0
			nrm[#nrm + 1] = ny
			nrm[#nrm + 1] = 0.0
		end
		for i = 0, sides - 1 do
			local i1
