					pos[#pos + 1] = y
					pos[#pos + 1] = z
					nrm[#nrm + 1] = x
					nrm[#nrm + 1] = y
					nrm[#nrm + 1] = z
					sl = sl + 1
				end
			end
			st = st + 1
		end
	end
