		return cached
	end
	if Dict.ContainsKey(self.missing, cp) then
		return nil
	end
	local gb = lub.font.glyph(self:Ttf(), cp, self.Px)
	if gb == nil then
		self.missing[cp] = true
		return nil
	end
	local u = 0
	local v = 0
	if gb.bytes ~= nil and gb.w > 0 and gb.h > 0 then
		if self.penX + gb.w + 1 > self.atlasW then
			self.penX = 1
			self.penY = self.penY + (self.rowH + 1)
			self.rowH = 0
		end
		if self.penY + gb.h + 1 > self.atlasH then
			print("lubx.Text: atlas full, glyph dropped: " .. cp)
			self.missing[cp] = true
			return nil
		end
		u = self.penX
		v = self.penY
		local src = 0
		do
			local row = 0
			while row < gb.h do
				local dst = ((v + row) * self.atlasW + u) * 4
				do
					local i = 0
					while i < gb.w do
						local a = gb.bytes:get(src)
						src = src + 1
						self.pixels[dst + 1] = 255
						self.pixels[dst + 1 + 1] = 255
						self.pixels[dst + 2 + 1] = 255
						self.pixels[dst + 3 + 1] = a
						dst = dst + 4
						i = i + 1
					end
				end
				row = row + 1
			end
		end
		self.penX = self.penX + (gb.w + 1)
		if gb.h > self.rowH then
			self.rowH = gb.h
		end
